function validateNIP(nip) {
  if (!/^\d{10}$/.test(nip)) return false;
  const weights = [6, 5, 7, 2, 3, 4, 5, 6, 7];
  let sum = 0;
  for (let i = 0; i < 9; i++) {
    sum += parseInt(nip[i]) * weights[i];
  }
  const remainder = sum % 11;
  if (remainder === 10) return false;
  return remainder === parseInt(nip[9]);
}

