def validate_nip(nip: str) -> bool:
    if not nip.isdigit() or len(nip) != 10:
        return False
    weights = [6, 5, 7, 2, 3, 4, 5, 6, 7]
    digits = [int(d) for d in nip]
    sum_val = sum(d * w for d, w in zip(digits[:9], weights))
    remainder = sum_val % 11
    if remainder == 10:
        return False
    return remainder == digits[9]

