public class NipValidator {
    public static boolean validate(String nip) {
        if (nip == null || !nip.matches("\\d{10}")) {
            return false;
        }
        int[] weights = {6, 5, 7, 2, 3, 4, 5, 6, 7};
        int sum = 0;
        for (int i = 0; i < 9; i++) {
            sum += Character.getNumericValue(nip.charAt(i)) * weights[i];
        }
        int remainder = sum % 11;
        if (remainder == 10) {
            return false;
        }
        return remainder == Character.getNumericValue(nip.charAt(9));
    }
}

