package main

import (
	"regexp"
	"strconv"
)

func ValidateNIP(nip string) bool {
	if matched, _ := regexp.MatchString(`^\d{10}$`, nip); !matched {
		return false
	}
	weights := []int{6, 5, 7, 2, 3, 4, 5, 6, 7}
	sum := 0
	for i := 0; i < 9; i++ {
		digit, _ := strconv.Atoi(string(nip[i]))
		sum += digit * weights[i]
	}
	remainder := sum % 11
	if remainder == 10 {
		return false
	}
	lastDigit, _ := strconv.Atoi(string(nip[9]))
	return remainder == lastDigit
}

