pub fn validate_nip(nip: &str) -> bool {
    if nip.len() != 10 || !nip.chars().all(|c| c.is_ascii_digit()) {
        return false;
    }
    let weights = [6, 5, 7, 2, 3, 4, 5, 6, 7];
    let digits: Vec<u32> = nip.chars().map(|c| c.to_digit(10).unwrap()).collect();
    let sum: u32 = digits.iter().take(9).zip(weights.iter()).map(|(&d, &w)| d * w).sum();
    let remainder = sum % 11;
    if remainder == 10 {
        return false;
    }
    remainder == digits[9]
}
